// ── Node 1: Validate Auth Secret ─────────────────────────────────
const headers = $input.first().json.headers || {};
const body    = $input.first().json.body    || {};
const secret  = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
const EXPECTED = 'medconnect-n8n-secret-key';

if (secret !== EXPECTED) {
  return [{ json: { success: false, statusCode: 401, error: 'UNAUTHORIZED_WEBHOOK_SECRET', source: 'n8n' } }];
}

// Pass through the full body + mark as authenticated
return [{ json: { ...body, _n8nAuthenticated: true, _n8nReceivedAt: new Date().toISOString() } }];

// ── Node 2: NLP Intent Extraction (Local Rule Engine) ────────────
// Runs entirely inside n8n. No external API needed.
// When OPENAI_API_KEY is set, the application layer calls OpenAI.
// This node applies rule-based fallback NLP so n8n always completes.

const data = $input.first().json;
if (data.error) return [{ json: data }]; // propagate auth failure

const text = (data.text || data.transcript || '').toLowerCase();
const lang = data.language || 'Hinglish';

let intent = 'UNKNOWN';
let confidence = 0.72;

if (/book|appointment|appoint|schedule|milna|chahiye|book karna/i.test(text)) {
  intent = 'BOOK_APPOINTMENT'; confidence = 0.95;
} else if (/cancel|bata|hatao|cancel kar/i.test(text)) {
  intent = 'CANCEL_APPOINTMENT'; confidence = 0.92;
} else if (/queue|token|number|kitna wait|status/i.test(text)) {
  intent = 'CHECK_QUEUE'; confidence = 0.91;
} else if (/doctor|available|kab|availability|kaun/i.test(text)) {
  intent = 'CHECK_DOCTOR_AVAILABILITY'; confidence = 0.88;
} else if (/emergency|urgent|icu|bed|blood|oxygen|ventilator/i.test(text)) {
  intent = 'EMERGENCY_RESOURCE_REQUEST'; confidence = 0.97;
} else if (/fee|due|bill|payment|kitna/i.test(text)) {
  intent = 'CHECK_DUES'; confidence = 0.86;
} else if (/address|timing|hospital|location|opd time/i.test(text)) {
  intent = 'GENERAL_HOSPITAL_QUERY'; confidence = 0.84;
}

// Slot extraction
const doctorMatch = text.match(/dr\.?\s+([a-z]+(?:\s+[a-z]+)?)|doctor\s+([a-z]+(?:\s+[a-z]+)?)/i);
const deptMap = { cardiology: 'Cardiology', ortho: 'Orthopedics', neuro: 'Neurology', derm: 'Dermatology', general: 'General Medicine' };
let department = '';
for (const [k,v] of Object.entries(deptMap)) { if (text.includes(k)) { department = v; break; } }

const slots = {
  doctorName: doctorMatch ? (doctorMatch[1] || doctorMatch[2]).trim() : null,
  department: department || null,
  date: /today|aaj/.test(text) ? new Date().toISOString().split('T')[0] : /tomorrow|kal/.test(text) ? new Date(Date.now()+86400000).toISOString().split('T')[0] : null,
  time: (text.match(/(\d{1,2}(?::\d{2})?\s*(?:am|pm|baje))/i) || [])[0] || null,
};

return [{ json: {
  ...data,
  _n8nIntent: intent,
  _n8nConfidence: confidence,
  _n8nSlots: slots,
  _n8nNLPAt: new Date().toISOString(),
  _n8nNLPEngine: 'n8n-rule-based-v2',
  source: 'n8n',
} }];

// ── Node 3: DB Validation & Action (Backend Logic inside n8n) ─────
// Validates slots and simulates the DB operation inside n8n.
// In production this node calls the backend API endpoint.

const d = $input.first().json;
if (d.error) return [{ json: d }];

const intent    = d._n8nIntent || 'UNKNOWN';
const slots     = d._n8nSlots  || {};
const lang      = d.language   || 'Hinglish';
const hospitalId= d.hospitalId || 'hosp-101';

let status = 'INFORMATIONAL';
let aiMessage = '';
let actionPayload = null;
let missingSlots = [];

switch(intent) {
  case 'BOOK_APPOINTMENT':
    if (!slots.doctorName && !slots.department) {
      missingSlots = ['doctorName','department','date'];
      aiMessage = lang === 'Hindi' ? 'मुझे आपके डॉक्टर का नाम और विभाग चाहिए।' : 'Aap kaun se doctor ya department mein appointment chahiye?';
      status = 'NEEDS_MORE_INFO';
    } else {
      const tokenNum = 'MED-' + (Math.floor(Math.random()*900)+100);
      actionPayload = { token: { token_number: tokenNum, status: 'CONFIRMED', doctor: slots.doctorName || 'Auto-assigned', department: slots.department || 'General Medicine', date: slots.date || new Date().toISOString().split('T')[0] } };
      aiMessage = lang === 'Hindi' ? `आपका अपॉइंटमेंट कन्फर्म हो गया है। टोकन नंबर: ${tokenNum}` : `Appointment confirmed! Token: ${tokenNum}. Please arrive 10 minutes early.`;
      status = 'ACTION_COMPLETED';
    }
    break;
  case 'CHECK_QUEUE':
    aiMessage = 'Aapka token queue mein hai. Estimated wait time: 15-20 minutes.';
    status = 'ACTION_COMPLETED';
    break;
  case 'CANCEL_APPOINTMENT':
    aiMessage = lang === 'Hindi' ? 'आपका अपॉइंटमेंट कैंसिल हो गया है।' : 'Appointment cancelled successfully.';
    status = 'ACTION_COMPLETED';
    break;
  case 'CHECK_DOCTOR_AVAILABILITY':
    aiMessage = 'Available doctors today: Dr. Rajesh Sharma (Cardiology 9AM-2PM), Dr. Priya Ananth (Ortho 10AM-4PM), Dr. Amit Patel (General 8:30AM-1PM).';
    status = 'ACTION_COMPLETED';
    break;
  case 'EMERGENCY_RESOURCE_REQUEST':
    aiMessage = '🚨 Emergency request registered. Nearby hospitals have been alerted. ICU beds being arranged immediately.';
    status = 'ACTION_COMPLETED';
    break;
  case 'CHECK_DUES':
    aiMessage = 'No pending dues found for your account. Consultation fee: ₹500.';
    status = 'ACTION_COMPLETED';
    break;
  case 'GENERAL_HOSPITAL_QUERY':
    aiMessage = 'Metro City General Hospital, 42 MG Road. OPD: 8AM-8PM Mon-Sat. Emergency: 24x7. Ph: 011-2345-6789.';
    status = 'INFORMATIONAL';
    break;
  default:
    aiMessage = lang === 'Hindi' ? 'मैं आपकी कैसे मदद कर सकता हूँ?' : 'Namaskar! Main aapki kya madad kar sakta hoon?';
    status = 'INFORMATIONAL';
}

return [{ json: {
  success: true,
  source: 'n8n',
  executedBy: 'local-n8n',
  workflowId: 'medconnect-ai-receptionist-v2',
  intent,
  confidence: d._n8nConfidence,
  status,
  aiMessage,
  actionPayload,
  missingSlots,
  validatedSlots: slots,
  transcript: d.text || '',
  language: lang,
  hospitalId,
  context: d.context || {},
  _n8nDBAt: new Date().toISOString(),
  configurationStatus: {
    openaiConfigured: false,
    sarvamConfigured: false,
    n8nConfigured: true,
  },
} }];

// ── Node 4: Build Final Response ─────────────────────────────────
const d = $input.first().json;
return [{ json: { ...d, _n8nCompletedAt: new Date().toISOString() } }];
